import { type GeneratorId } from "./campaign-generator-types";

export const EXEMPLARS: Record<GeneratorId, string> = {
  "mystery-investigation": `{"title":"The Understudy's Last Bow","summary":"The lead actor collapses during the second act, leaving three testable accounts and one night before the run resumes.","content":"## Opening Hook\\nThe company's star fell mid-scene, and the understudy was already in costume.\\n\\n## Central Question\\nWho changed the stage wine, and when?\\n\\n## Evidence\\n- The prop goblet smells of crushed foxglove; it shows the drink was tampered with but not who poured it.","lore":"## Fixed Truth — GM Only\\nThe stage manager dosed the wine to stop the lead from signing with a rival company.\\n\\n## Timeline\\n1. The wine was changed during the interval.\\n2. The culprit moved the understudy's call so it looked planned.","labels":["mystery","investigation","mystery-generator"],"connections":[]}`,
  puzzle: `{"title":"The Ember Choir","summary":"Three cracked braziers seal the reliquary while a sleeping guardian listens for a forgotten hymn.","content":"## Player-Facing Setup\\nThe vault door is ringed by three braziers whose flames burn different colours.\\n\\n## GM-Only Solution\\nThe braziers respond to a sequence suggested by the frescoes; players can also disrupt the ward, bargain with the guardian, or force open a brazier at a cost.\\n\\n## Clues\\n- **Obvious clue:** The frescoes show the colours in order.\\n- **Discoverable clue:** Ash marks reveal one brazier was recently reset.\\n- **Emergency clue:** A flame leans toward the next brazier after any meaningful attempt.\\n\\n## Character Spotlight Opportunities\\nArcane knowledge, careful observation, physical force, and creative magic each reveal a useful angle.\\n\\n## Alternate Solutions\\n- Break a brazier and awaken the guardian.\\n- Offer the guardian a true memory.\\n\\n## Failure & Escalation\\nEach mistake advances the guardian's waking, but reveals another clue.\\n\\n## Escalating Hints\\n1. The mural is a sequence.\\n2. The colours are ordered by the figures' hands.\\n3. The blue brazier is first.\\n\\n## Running the Puzzle\\nDescribe all three braziers and the mural freely; never hide the sequence behind a roll.\\n\\n## Scaling\\nUse two braziers for a simpler version or add a clock for a harder one.","lore":"### At a Glance\\n- **Difficulty:** Challenging\\n- **System:** System-neutral","labels":["puzzle","puzzle-generator","magical"],"connections":[]}`,
  npc: `{"title":"Hesper Quayle","summary":"A mountain midwife who has delivered half the valley and remembers which births were never recorded.","lore":"## Who She Is\\nHesper walks the high pastures between farmsteads with a mule and a bag of herbs, and every family owes her a child's first breath.\\n## Secret\\nDuring the fever winter she swapped two newborns to save one of them, and both families are now feuding over grazing rights.\\n## Hook\\nShe asks the party to escort her over the pass in a snowstorm, because a birth she promised to attend cannot wait.","labels":["Midwife","Herbalist"],"connections":[{"targetTitle":"Wardens of the High Pass","relationship":"trusted by"}]}`,
  faction: `{"title":"The Kiln Sisters","summary":"A potters' cooperative that rules the valley by deciding whose clay gets fired.","lore":"## What They Control\\nThe only kilns hot enough for roof tiles and water pipes, so every new house and well waits on their schedule.\\n## Internal Conflict\\nThe elder sisters want to keep the craft secret; the apprentices want to sell the glaze recipe to the capital.\\n## Hook\\nA kiln has cracked from the inside, and the sisters suspect sabotage by someone among their own.","labels":["Craft Cooperative","Rural Power"],"connections":[{"targetTitle":"Hollowfold","relationship":"based in"}]}`,
  settlement: `{"title":"Hollowfold","summary":"A terraced vineyard town built inside the crater of a sleeping volcano.","lore":"## Points of Interest\\nThe Steam Baths sit over a living vent; the Terrace Steps climb nine hundred stairs to the rim.\\n## Power Structure\\nThe family that owns the hot springs sets the price of every bath, laundry and greenhouse.\\n## Hook\\nThe springs have gone cold overnight, and the vines will not survive a frost without them.","labels":["Crater Town","Vineyard"],"connections":[{"targetTitle":"The Kiln Sisters","relationship":"home of"}]}`,
  "magic-item": `{"title":"Thornwright's Compass","summary":"A brass compass whose needle always points to the last thing its holder lost.","lore":"## History\\nMade by a hedge-witch for a forgetful husband, it passed through three pawnshops before anyone understood it.\\n## Power\\nThe needle finds any lost object, animal or person the holder has personally lost, at any distance.\\n## Cost\\nEach use makes the holder forget one small, unrelated thing they will need later.","labels":["Wondrous Item","Uncommon"],"connections":[{"targetTitle":"Hollowfold","relationship":"pawned in"}]}`,
  "minor-magic-item": `{"title":"Cinder Needle","summary":"A charred bone needle that mends torn cloth with a glowing seam, exhausting its heat after three repairs.","lore":"### Quick Reference\\n- **Item Form**: Disposable Tool\\n- **Usage Limit**: Fragile Charges (3 uses)\\n- **Activation**: Threading and pulling through fabric\\n- **Primary Utility**: Crafting & Utility\\n\\n### Magical Effect & Mechanics\\nWhen pulled through torn cloth or leather, the needle emits a soft orange glow and fuses the material seamlessly with heat, leaving no stitch marks. It loses its warmth and crumbles to grey ash after mending three tears.\\n\\n### Quirk or Drawback\\nMended seams smell faintly of toasted cedar for a week.\\n\\n### Suggested Use in Play\\nQuickly repairing torn banners, punctured water skins, or damaged disguises in the field.\\n\\n### Provenance & Rumour\\nCrafted by a travelling stitcher who traded them to frontier scouts in exchange for dried rations.","labels":["minor-magic-item","consumable","trinket"],"connections":[{"targetTitle":"Frontier Scouts' Lodge","relationship":"traded to"}]}`,
  artifact: `{"title":"The Sun-Shattered Aegis","summary":"A legendary shield of meteoric gold forged in the First Age that blinds foes and bends lightning, but slowly drains the bearer's mortal lifespan.","content":"### Description\\nThe Aegis is a massive tower shield hammered from an alloy of true gold and fallen starlight. Its surface is engraved with the genealogy of lost high kings, and it hums with deep harmonic vibration when hostile blades are drawn.","lore":"### Quick Reference\\n- **Item Form**: Weapon / Implement of War\\n- **Origin Era**: Primordial / Mythic Age\\n- **Power Tier**: Heroic Wonder (Alters individuals & skirmishes)\\n- **Current Status**: Sealed in Royal / High-Security Vault\\n- **Curse / Cost**: Sacrificial Price (Requires vital tribute/blood)\\n- **Setting / Theme**: Classic Fantasy\\n\\n### Artifact Powers & Manifestations\\n- **Dormant Powers**: The bearer cannot be knocked prone or moved against their will; missile attacks suffer severe deflection.\\n- **Awakened Powers**: When struck, can release a blinding flash of celestial dawn light that disorients and sears supernatural attackers.\\n- **Ascendant / Zenith Powers**: Creates a hundred-pace sanctuary dome that halts cataclysmic magic and artillery for one hour.\\n\\n### Attunement & Awakening Requirements\\nMust be held aloft before the rising sun while swearing an unbreakable sovereign oath to defend the land with one's life.\\n\\n### Cost, Curse, Corruption, or Taboo\\nEach activation of its awakened light ages the bearer by one lunar month, turning their hair frost-white.\\n\\n### Known History & Previous Keepers\\nBorne by King Alden at the Siege of Sunken Spire, where he held the breached gate alone until dawn.\\n\\n### Interested Factions & Pursuers\\nThe Sun-Sworn Paladins seek to reclaim it as holy regalia; the Ashen Court wishes to melt it down to extinguish its ward.\\n\\n### Rumours & Conflicting Legends\\nCommon folk believe the shield makes its wielder immortal, confusing the bearer's sacrifice with invulnerability.\\n\\n### Adventure Hooks\\nThe royal vault holding the shield is scheduled to be opened during the solar eclipse; a conspirator aims to replace it with a gilded lead replica.\\n\\n### Destruction or Sealing Conditions\\nCan only be shattered if struck by a weapon forged by the same celestial blacksmith at the exact moment of a sovereign's betrayal.","labels":["artifact","relic","shield","legendary"],"connections":[{"targetTitle":"Royal Treasury of Aldmere","relationship":"housed in"}]}`,
  event: `{"title":"The Year of Silent Hives","summary":"The spring every beehive in the province stood empty, and the orchards bore no fruit.","lore":"## Summary\\nFor one season no bee returned to any hive; the blossom fell unpollinated and the harvest failed.\\n## Causes\\nNo one agrees — a new pesticide from the capital, a beekeepers' curse, a queen-taking swarm from the east.\\n## Consequences\\nHoney became currency, orchard families sold their land, and hand-pollinating children became a guild.\\n## Hook\\nThis spring, one hive in a remote village is humming again, and three buyers are already on the road.","labels":["Disaster","Agrarian"],"connections":[{"targetTitle":"The Pollinators' Guild","relationship":"created"}]}`,
  ship: `{"title":"CSV Meridian","summary":"A worn freighter that earns its living asking no questions — and keeping no honest records.","lore":"## Who Controls It\\nIndependent in name; in practice, whoever can pay the docking fees this month.\\n## Complication\\nThe cargo manifest lists machine parts. The hold contains neither machines nor parts.\\n## Secret\\nThe ship was declared lost seven years ago. The captain has a very good reason for keeping it that way.\\n## Hook\\nThe Meridian is the only vessel in port that will run this route — but the crew wants something in return.","labels":["Freighter","Sci-Fi","Independent"],"connections":[{"targetTitle":"Orbital Customs Directorate","relationship":"flagged by"}]}`,
  "news-sheet": `{"title":"The Ridgeline Crier — Issue 37","summary":"A mining-town broadsheet whose lead story about a shaft collapse carefully avoids naming who ordered the night shift.","lore":"# The Ridgeline Crier\\n*Printed by lamplight, read by everyone — Issue No. 37*\\n\\n## SHAFT SEVEN FALLS IN: 'NOBODY BELOW', SAYS THE COMPANY\\nThe old north gallery of Shaft Seven collapsed before dawn. The company says the gallery was closed. The canteen cooked forty breakfasts that nobody came up to eat.\\n\\n### Company Announces Safety Bonus\\nThe Ridge Mining Company will pay a bonus to crews who return to work by Monday. The bonus has no stated amount.\\n\\n### Notices & Classifieds\\n- FOUND: one canary cage, empty, near the Shaft Seven headframe. Owner may collect from the Crier office.\\n- WANTED: experienced timber-men, no questions about previous employers.\\n\\n### Word on the Street\\n- The pumps on Shaft Seven were switched off two days before the collapse, say the pump-boys.\\n\\n## GM Notes\\n**The truth**: the foreman sent a crew into the closed gallery to strip its silver seam before the company sold the claim; six miners are trapped alive in an air pocket.\\n**Hooks**: a trapped miner's sister will pay the party to dig before the company floods the shaft; the pump-boy who switched off the pumps is hiding in the assay office.","labels":["broadsheet","mining-town","handout"],"connections":[{"targetTitle":"Ridge Mining Company","relationship":"covers for"}]}`,
  language: `{"title":"Low-Speak","summary":"A guttural, whispered dialect used by miners and tunnel-diggers to communicate across echoing caverns.","content":"## Pronunciation & Phonology\\nLow-frequency clicks, soft whistles, and deep guttural stops that carry well through stone.\\n\\n## Cultural Role & Usage\\nSpoken in the deep galleries where torchlight is rationed; surface-folk who use it mark themselves as tunnel-kin.\\n\\n## Naming Conventions\\nNames are formed by compound roots relating to geological features or mineral properties.\\n\\n## Common Vocabulary & Word Bank\\n| Word | Pronunciation | English Meaning |\\n| --- | --- | --- |\\n| Vur | VOOR | Iron |\\n| Lith | LITH | Stone |\\n\\n## Sample Phrases\\n- *\\"Vur-Lith-Garon\\"* — (VOOR-lith-GAH-ron) — \\"Solid as iron\\"","lore":"### At a Glance\\n- **Genre / Setting**: Classic Fantasy\\n- **Tone**: Harsh & Consonant-heavy\\n- **Role**: Common Speech\\n- **Name Structure**: Compound Words\\n\\n### Example Names\\n- **Garon-Vur** — Iron Seeker (person)\\n- **Kael-Lith** — Stone Speaker (person)\\n\\n### At the Table\\n- Greet with a short falling whistle before speaking; skipping it reads as a threat.","labels":["dialect","underdark","conlang"],"connections":[]}`,
  dungeon: `{"title":"The Submerged Vault of Sunken Runes","summary":"An ancient flooded temple complex whose inner sanctum preserves an active celestial beacon.","lore":"## History & Original Purpose\\nOriginally built 800 years ago as a sacred dwarven sanctuary, the delve was abandoned during the Dragon War and subsequently flooded by subterranean rivers.\\n## Current State & Function\\nCurrently overrun by a desperate clan of Goblins utilizing ancient defense traps against an intruding Kobold mining party.\\n## Signature Feature\\nThe Levitating Sunstone: A massive radiant orb suspended over an inverted fountain pool, illuminating the entire central hall.\\n## Current Conflict\\nAn invading Kobold mining crew has broken into the lower sectors, sparking a turf war with the resident Goblin clan.\\n## Key Sectors & Layout\\n### Sector 1: The Guarded Gateway\\nFortified entry halls with collapse traps.\\n### Sector 2: The Deep Arcana Vault\\nSealed inner chamber housing warding circles.\\n## Inhabitants & Factions\\nA desperate clan of Goblins utilizing ancient defense traps against an intruding Kobold mining party.\\n## Central Secret / Boss Mystery\\nThe dungeon was not built as a tomb, but as a vault to lock away an elemental planar core.\\n## Hazards & Traps\\nPressure-plate needle traps laced with paralyzing wyvern venom.\\n## Treasures & Artifacts\\nA silver-hilted shortsword glowing with pale starlight near undead.\\n## Adventure Hooks & Rumours\\nA local scholar hires the party to retrieve an ancient astrological tablet from the ruins.","labels":["dungeon","location","fantasy","temple-shrine"],"connections":[]}`,
  adventure: `{"title":"The Cartographer's Daughter","summary":"A mapmaker's daughter vanishes carrying the only survey of a border pass, and both kingdoms want it before the snows close the road.","lore":"## Initial Situation\\nThe mapmaker's daughter left the surveyor's house at night with a sealed case. Her father swears she is alive and wants her found.\\n## Primary Objective & Pressure\\nReach the girl and the survey before the snows close the pass in six days.\\n## Key Locations\\n- **The Surveyor's House** — Stacked with unfinished sketches; one room is locked from the inside.\\n- **Crossing Hut** — The last shelter on the pass, run by a widow who records everyone who climbs.\\n## Important NPCs & Factions\\n- **Ines Varro, the daughter** — Fled after finding a boundary marked in the wrong place; wants the error corrected quietly.\\n- **Captain Hask** — Border officer who loses his commission if the error surfaces.\\n## Threats & Antagonists\\n- Two riders from the capital follow the same trail with orders to take the survey without asking questions.\\n## Clues, Secrets & Discoveries\\n- The survey shows the pass is two miles narrower than the treaty claims, which is why both sides are watching.\\n## Complications & Escalating Pressures\\n- The surveyor has been arrested for forgery, which strengthens the capital's case for seizing the survey.\\n## Possible Outcomes\\n- The survey reaches the treaty commission and the boundary is redrawn with Ines's correction on record.\\n- The survey is burned; Ines survives but the error stays buried.\\n## Adventure Hooks\\n- A courier reaches the inn with a letter addressed to the party, sealed with the surveyor's mark.\\n- A reward notice offers coin for word of a young woman carrying a brass tube.","labels":["adventure","investigation","fantasy"],"connections":[]}`,
  quest: `{"title":"The Orchard That Walks","summary":"An old apple grove creeps a little closer to the village every night, and its roots have reached the first cottage.","lore":"## Quest Hook\\nThe miller begs the party to stop the grove before it reaches the mill race at the next full moon.\\n## Threat\\nA dryad whose heartwood tree was felled is moving her grove to find the person who sold it.\\n## Complication\\nThe miller's own son sold the heartwood to a shipwright, and the miller knows it.\\n## Reward\\nThe village offers grazing rights on the common and a cask of the grove's last cider.","labels":["rpg-quest","quest-generator","pastoral"],"connections":[]}`,
  rumour: `{"title":"Word Around Ferrin Glassworks","summary":"Six local rumours for a glassworks town. Every one names a concrete lead, and exactly one is a dangerous misconception.","content":"### Rumour 1\\n- **Rumour**: Old Sabine swears the number three furnace roars at night with nobody tending it, and it burned blue last Tuesday.\\n- **Lead**: Old Sabine, the number three furnace\\n- **Source**: a night-shift stoker\\n\\n### Rumour 2\\n- **Rumour**: The foreman has been paying the carters to ignore two unlabelled crates every week.\\n- **Lead**: the foreman, the east loading bay\\n- **Source**: a carter\\n\\n### Rumour 3\\n- **Rumour**: A boy clearing the old sand pit found a glass figure with its eyes still moving, then sold it to a stranger before dawn.\\n- **Lead**: the sand pit, the stranger\\n- **Source**: a market boy\\n\\n### Rumour 4\\n- **Rumour**: Cattle keep turning up at the orchard edge with blistered hooves, and two pickers swear they saw a figure walking on the glass.\\n- **Lead**: the orchard\\n- **Source**: a picker\\n\\n### Rumour 5\\n- **Rumour**: The guild has been meeting in the assay house at odd hours, and members who leave early will not say what was decided.\\n- **Lead**: the guild, the assay house\\n- **Source**: a guild apprentice\\n\\n### Rumour 6\\n- **Rumour**: Master Ilse has not been seen in five days, last spotted near the river bridge arguing with someone no one can name.\\n- **Lead**: Master Ilse, the river bridge\\n- **Source**: a bread seller","lore":"### At a Glance\\n- **Genre**: Classic Fantasy\\n- **Tone**: Gossipy\\n- **Danger Level**: Moderate\\n\\n### GM Notes — Rumour 1\\n- **Reality**: essentially true\\n- **What's Actually Happening**: a buried vein of unstable ore feeds the furnace and burns blue when cooled too fast.\\n- **If Investigated**: the vein can be sealed, or sold to the guild for a fortune.\\n\\n### GM Notes — Rumour 2\\n- **Reality**: essentially true\\n- **What's Actually Happening**: the foreman smuggles unlicensed glass out through the carters and bribes a sergeant to keep the gate quiet.\\n- **If Investigated**: following the sergeant leads straight to the next shipment, still in transit.\\n\\n### GM Notes — Rumour 3\\n- **Reality**: exaggeration\\n- **What's Actually Happening**: the figure was a cheap clockwork toy, and the stranger is a collector who will pay for more.\\n- **If Investigated**: the collector is tracking a genuine cache one level deeper in the pit.\\n\\n### GM Notes — Rumour 4\\n- **Reality**: essentially true\\n- **What's Actually Happening**: a lynx has denned beside the orchard and is taking calves at dusk.\\n- **If Investigated**: tracking it to the den reveals cubs, which changes how the encounter should be handled.\\n\\n### GM Notes — Rumour 5\\n- **Reality**: essentially true\\n- **What's Actually Happening**: the guild is preparing to raise furnace prices across the whole town.\\n- **If Investigated**: a sympathetic apprentice describes the plan in exchange for protection.\\n\\n### GM Notes — Rumour 6\\n- **Reality**: dangerous misconception\\n- **What's Actually Happening**: Ilse left of her own accord to escape a contract and is safe elsewhere under a different name.\\n- **If Investigated**: a public search could expose her to the very people she fled.","labels":["rumour-generator","local-rumours","imported-draft"],"connections":[]}`,
  villain: `{"title":"Corvin Ashmere, the Quiet Hand","summary":"A magistrate beloved for ending a famine who is quietly starving the city's rivals to keep it that way.","content":"### Public Face\\nCorvin Ashmere is celebrated as the magistrate who broke the Long Famine, and his portrait hangs in half the granaries he saved.\\n### Signature / Calling Card\\nEvery rival merchant house he ruins fails a routine grain inspection first — always the same clause, always enforced to the letter.\\n### First Signs\\n- Two independent grain houses have failed inspection this month, both healthy a season ago.\\n- The city watch has stopped patrolling the old grain exchange district.","lore":"### Core Concept\\nA beloved reformer who is deliberately re-engineering the city's food supply into a single point of control he alone holds.\\n### True Nature\\nThe famine he ended was worsened, not solved, by grain he quietly withheld until his reforms could take credit for the recovery.\\n### Ultimate Goal\\nEvery granary in the city answers to a single authority — his — before the next bad harvest can be blamed on anyone else.\\n### Why Now\\nThe city's charter permits emergency requisition powers only while famine memory is fresh; that window is closing.\\n### Motivation\\nHe genuinely believes concentrated control prevents another famine, and no longer distinguishes that belief from his own ambition.\\n### Fatal Flaw\\nHe cannot tolerate being contradicted by someone he once helped, and will expose himself to stop it personally.\\n### Methods\\nSelective inspections, requisition law, and quiet leverage over the watch captains who enforce it.\\n### Resources\\nThe city's requisition charter, a loyal inspectorate, and the genuine gratitude of half the population.\\n### Lieutenants & Inner Circle\\n- **Dessa Rook** — Chief Inspector. Loyal from genuine belief; has not yet been asked to falsify a healthy inspection and does not know how she would answer.\\n- **Halvard Prine** — Watch Captain. Loyal for the pension it buys him; keeps copies of every irregular order in case he needs to bargain later.\\n### Organisation & Power Structure\\nA public inspectorate with real legal authority, quietly staffed at the top with people who owe Corvin their careers.\\n### Territory / Lair\\nThe old grain exchange, legitimately his office, its lower vaults holding the withheld surplus no audit has reached.\\n### The Villain's Plan\\n**Stage 1: Fail the independents** — Use inspections to close two rival grain houses. Clues: suspicious failed inspections. Disruption exposes the inspection standard as selectively enforced.\\n**Stage 2: Absorb their contracts** — Redirect their customers to his own network. Clues: new exclusive supply contracts. Undisrupted, dependency deepens quietly.\\n**Stage 3: Extend requisition powers** — Petition to make emergency powers permanent, citing continued risk. Clues: a suspiciously well-timed near-shortage. Disruption forces a public vote he might lose.\\n**Stage 4: Remove the last independent auditor** — Discredit or reassign whoever could still inspect his own vaults. Clues: a sudden transfer order. This is the last stage stoppable without a direct confrontation.\\n**Stage 5: Consolidate the charter** — Formalise permanent control of the grain supply. Clues are now public record. Stopping this requires exposing Stage 1 outright.\\n### Escalation If Ignored\\nBy Stage 4 he controls inspection of his own operation; by Stage 5 the charter is law and undoing it means overturning an act of the city council.\\n### Discovery Layers\\n**What the World Knows**: Corvin ended the famine and now proposes permanent reforms to prevent another.\\n**What Their Servants Know**: inspections have become selectively harsh, though most assume it is zeal, not design.\\n**GM-Only Truth**: the original famine was prolonged deliberately, and the withheld grain still sits in his vaults.\\n### Personal Connections\\n- A party member's family grain house was one of the 'failed' inspections.\\n- Corvin personally thanked a PC's mentor during the famine relief, a favour he now expects repaid with silence.\\n### Weakness / Vulnerability\\nThe withheld surplus in his vaults is physical evidence that cannot pass any inspection but his own — get an independent inspector inside and the whole account collapses.\\n### Moral Complication\\nHis reforms, corrupt as they are, genuinely did prevent a second famine; removing him without a real alternative risks the shortage returning.\\n### Final Confrontation\\nExposing him publicly during a council vote risks a food-supply panic that could hurt the city as much as his control does.\\n### If Defeated\\nThe inspectorate fractures without him, the withheld surplus must be redistributed carefully to avoid a price collapse, and Dessa Rook is left to decide whether the system he built can be salvaged or must be torn down.","labels":["villain","bbeg-generator","urban"],"connections":[{"targetTitle":"City of Varn","relationship":"controls the grain supply of"}]}`,
  "plot-twist": `{"title":"The Mercy That Bought Time","summary":"The duke's loyalty is genuine, but the sacrifice keeping his army supplied has created a crisis the party must choose how to expose.","reveal":"The duke diverted the war treasury to prevent a famine, and the missing funds are now being used to manipulate the campaign.","believedAssumption":"Everyone believes the duke's unexplained absence of supplies proves he is secretly aiding the enemy.","rationale":"The known shortages and the duke's loyalty are both true; only the motive and consequence were misunderstood.","foreshadowing":["The poorest districts have unusually full grain stores.","The duke refuses a public audit but quietly protects a group of civilian clerks.","Enemy scouts avoid villages that should be easy targets."],"immediateConsequences":["The army's next offensive must be delayed or risk starving civilians.","Exposing the duke may restore political trust while destroying the emergency food network."],"newChoices":["Protect the duke's secret and find another way to supply the army.","Reveal the truth and force the nobles to choose between victory and famine.","Use the evidence to negotiate a public settlement with the enemy."],"lore":"### GM Note\\nThe twist preserves the established facts and turns the players' proof into leverage rather than a simple accusation.","labels":["complication","moral-dilemma","political"]}`,
  world: `{"title":"Khepri IV","summary":"A tidally locked desert world whose settlements cling to the narrow belt of dusk between a molten dayside and frozen night.","lore":"## World Profile\\nKhepri IV is a frontier world where every border follows the shade line.\\n## Climate & Geography\\nThe terminator belt migrates slowly, forcing towns to move their farms and roads with it.\\n## Gravity, Atmosphere & Biosphere\\nThe air is breathable but carries abrasive dust; native life burrows beneath the cooling surface.\\n## Settlements, Cultures & Factions\\nThe twilight cities share water through a fragile compact, while a solar-mining consortium wants to break it.\\n## Economy, Resources & Technology\\nMirror arrays harvest dayside energy, but only the cities can distribute it safely.\\n## Hazards & History\\nA failed weather-engineering project widened the dayside by three kilometres.\\n## Notable Locations\\n- The Moving Capital — a city on crawler treads.\\n- The Glass Sea — dunes fused by solar storms.\\n- The Cold Gate — the only protected route into the nightside.\\n## Mysteries & Conflicts\\nThe old climate array is receiving commands from somewhere beneath the Glass Sea.\\n## Adventure Hooks\\n- A water convoy has vanished beyond the Cold Gate.\\n- The consortium offers a fortune for a map of the buried array.\\n- A city refuses to move with the terminator, and its people need another solution.","labels":["world","desert-world","frontier","hard-sci-fi"],"connections":[]}`,
  constellation: `{"title":"The Seven Spears","summary":"A seven-star constellation the Kesh Riders read as the spears of their first chieftains, used to mark the autumn migration.","lore":"## Seasonal Visibility\\nVisible low on the horizon after sunset through the cold months, sinking out of sight by early summer.\\n## Practical Use\\nUsed by the Kesh Riders to mark the start of the autumn migration.\\n## Cultural & Religious Meaning\\nRegarded by the Kesh Riders as the spears of their first chieftains, planted in the sky at the end of the founding war.\\n## Omens\\nThe Kesh Riders hold that if it dims before its usual season, a promise long thought kept is about to be broken.\\n## Adventure Hook\\nA member of the Kesh Riders insists the Seven Spears rose out of season this year, and wants the party to find out why before the rest of the camp panics.","labels":["constellation","classic-fantasy","weapon","navigation"],"connections":[]}`,
  "star-system": `{"title":"Kesh-9","summary":"A contested binary system whose fragile water compact is the only thing keeping two mining powers from open war.","lore":"## Core Concept\\nKesh-9 is a hard sci-fi binary system, contested in character and frontier in reach, valued for a rare isotope deposit found nowhere else on the charted lanes.\\n## The Star(s)\\nA close binary pair locks the system into overlapping shadows and unstable seasons.\\n## Major Bodies\\n- **Kesh-9 II** (Temperate World) — the system's one habitable body, and its most fought-over resource.\\n- **Kesh-9 III** (Asteroid Belt) — worked by independent crews who answer to no single authority.\\n- **New Halden** (Derelict Station) — abandoned mid-construction, its original purpose still disputed.\\n- **Kesh-9 IV** (Ice Giant) — its atmosphere mined for volatiles by orbital skimmers.\\n## Settlements & Factions\\nA handful of independent outposts hold the system together. The Kesh Compact favours the current water-sharing treaty; the Vantage Drilling Concern wants to break it for exclusive isotope rights.\\n## Resources & Strategic Importance\\nThe isotope deposit on Kesh-9 III is the system's leverage — whoever controls extraction rights controls the system's politics.\\n## Travel Hazards\\nGravitational surges between the twin stars scramble navigation near closest approach.\\n## History\\nThe current balance dates to the last treaty renegotiation, when the isotope deposit was first confirmed.\\n## System-Wide Conflict or Mystery\\nNew Halden was abandoned mid-construction for reasons neither faction will discuss, and its dormant systems have recently begun drawing power again.\\n## Adventure Hooks\\n- The Kesh Compact needs outside investigators to learn why New Halden woke up before the Concern finds out first.\\n- A supply convoy vanishes during a gravitational surge event, and both factions blame the other.\\n- Someone on Kesh-9 II is quietly negotiating to sell isotope rights out from under the Compact.","labels":["star-system","binary-system","hard-sci-fi","contested","frontier"],"connections":[]}`,
  "council-vote": `{"title":"The Quarantine Vote for Hab Ring Six","summary":"The five-seat Ring Council must lift a quarantine within three days, and a rival syndicate is quietly buying votes to keep the ring sealed.","lore":"## The Proposal\\nLift the quarantine on Hab Ring Six so the patron's freight line can dock again and the sealed food stores can be sold.\\n## Deadline & Stakes\\nThe council charter requires the motion to be called before the next station cycle, three days away. If it fails, the quarantine cannot be reviewed until next year and the patron's freight company collapses.\\n## Voting Procedure\\nSimple majority of five seats; the Chair may break a tie but cannot otherwise vote.\\n## Current Vote Estimate\\nTwo leaning in favour, one opposed, two undecided.\\n## Council Members\\n- **Idris Vale, Council Chair** (Traditionalist) — Public position: neutral pending evidence. True agenda: wants precedent and expert testimony before committing; privately resents pressure from either side. Persuaded by: a formal audit of the ring's last inspection. Hook: his aide gambles on the lower decks and owes money to a smuggler who would trade information for forgiveness.\\n- **Sunniva Kolt** (Beleaguered Ally) — Public position: supports lifting it. True agenda: sympathetic to the patron, but her seat depends on a dock guild that opposes new cargo. Persuaded by: a face-saving amendment that places the freight line under guild administration. Hook: the guild holds her family's arrears and wants the party to clear them.\\n- **Devrin Mott** (Syndicate's Agent) — Public position: opposed. True agenda: answers directly to the syndicate that funds the blockade and will not be moved by persuasion. Persuaded by: nothing; better exposed than courted. Hook: his correspondence with the syndicate's agent is hidden in a locked cabinet in his quarters.\\n- **Yeva Hallam** (Greedy Broker) — Public position: undecided. True agenda: will vote however benefits her shipping contracts, and is soliciting offers from both sides. Persuaded by: a better contract than the syndicate is offering. Hook: exposing her as an open vote-seller would cost her the seat, which is leverage in itself.\\n- **Tobiah Anand** (Idealist) — Public position: supports lifting it. True agenda: genuinely believes the ring should reopen, but will withdraw support if the party's methods harm ordinary workers. Persuaded by: proof that reopening protects the people in the lower decks, not only the merchants. Hook: he is already drafting a labour-protection clause the party could champion for him.\\n## Antagonist Influence\\nEntrenched. The syndicate has bought Devrin outright and is bidding for Yeva. Expect a countermove within a day of any public progress toward a majority.\\n## Investigation Leads\\nThe station's cargo log shows unusual fees routed through Yeva's contracts. Sunniva's guild hall keeps the record of her family's arrears. Idris's aide drinks in the lower-deck canteen most nights.\\n## Possible Paths\\nSecure Idris's audit and Tobiah's clause to win a clean majority of three, or expose Devrin and outbid the syndicate for Yeva to force a 3-2 vote without ever winning Idris over.\\n## Follow-Up Hooks\\nWhichever way Yeva sells her vote, she will remember who paid better. Exposing Devrin publicly earns the syndicate's open enmity rather than its quiet one.","labels":["council-vote","political-intrigue","quest"],"connections":[{"targetTitle":"Ring Council","relationship":"governing body of"}]}`,
  "alien-race": `{"title":"Ith'vareen","summary":"A six-limbed species whose chemical speech makes their emotions public and their motives unreadable.","lore":"## Overview\\nThe Ith'vareen are a hard sci-fi species with six limbs, the forward pair specialised for fine work, native to a high-gravity world.\\n## Evolutionary Origin\\nHeavy gravity selected for compact frames and cautious movement; a fall at home is usually fatal, so recklessness never became a virtue.\\n## Homeworld & Environment\\nTheir world weighs nearly twice what visitors expect, and their architecture assumes it.\\n## Biology & Lifecycle\\nSix limbs, four load-bearing, and a working lifespan of roughly ninety years.\\n## Senses, Communication & Psychology\\nThey speak in emitted chemical signals, so emotional state is broadcast whether or not they intend it — they cannot lie about how they feel, only about why.\\n## Culture & Social Structure\\nThey have no concept of \\"free hands\\": standing, carrying and working are simultaneous, and idleness reads to them as illness.\\n## Technology\\nTools are built for three-point grip and are near-unusable by two-handed species; their script runs in three parallel columns because three limbs write at once.\\n## Beliefs & Worldview\\nA truth nobody has agreed to is treated as a proposal, which outsiders mistake for relativism.\\n## Relations with Outsiders\\nTrade works, which is exactly why neither side has had to resolve what they think of each other.\\n## Internal Factions & Conflicts\\nOne faction would trade their structural engineering openly for standing; another calls that the first step to being absorbed.\\n## Weaknesses & Constraints\\n- The forward limbs break easily, and losing one is a maiming their medicine has never solved.\\n- Standard gravity feels unsafe to them; they misjudge distances constantly off-world.\\n## Naming Conventions\\nSpoken names are transliterations of a scent-signature, with several equally valid written forms.\\n## Typical Archetypes\\n- **The Intermediary** — works comfortably with outsiders, and is quietly distrusted at home for it.\\n## Adventure Hooks\\n- A delegation needs an outsider to carry a message their own speech cannot safely encode.","labels":["alien-race","hard-sci-fi","hexapodal","high-gravity-world"],"connections":[]}`,
  "faction-roster": `{"title":"The Ironwood Rangers' Inner Circle","summary":"Four senior Rangers split between the old wardens who guard the forest and the young riders who want it opened to settlers.","content":"### Marta Oake — Ranger Captain\\n- **Duty**: Commands the patrols and signs every permit that leaves the forest.\\n- **Motive**: Wants the forest kept intact for another generation, whatever it costs the settlers.\\n- **Stance**: Loyalist\\n- **Trait**: Never raises her voice, which is how everyone knows when she is angry.\\n- **Wants right now**: Needs one more patrol captain to vote with her before the settlers' petition is read.\\n- **Leverage**: Holds the only copy of the old boundary map.\\n- **Connection**: distrusts, and is quietly outmanoeuvred by (Joss Penrow)\\n\\n### Joss Penrow — Riders' Spokesman\\n- **Duty**: Leads the young riders and speaks for them at the council fires.\\n- **Motive**: Wants the forest opened to settlers before the next dry season ruins the valley farms.\\n- **Stance**: Reformer\\n- **Trait**: Remembers every promise anyone has made to him, in order.\\n- **Wants right now**: Needs the petition read at the next fire, before Marta can delay it.\\n- **Leverage**: Has been quietly guiding settler wagons through the north trail.\\n- **Connection**: undermines, while pretending to serve (Marta Oake)\\n\\n### Bram Teller — Quartermaster\\n- **Duty**: Keeps the supply cellars and arranges trade with the lowland towns.\\n- **Motive**: Wants the trade route kept open without anyone asking how the goods were gathered.\\n- **Stance**: Opportunist\\n- **Trait**: Agrees with whoever spoke to him most recently.\\n- **Wants right now**: Needs the north trail kept quiet for one more week.\\n- **Leverage**: Has been selling spare timber to a lowland mill behind the council's back.\\n- **Connection**: owes a favour to, and privately fears (Joss Penrow)\\n\\n### Ysolde Crane — Scout\\n- **Duty**: Tracks game and strangers, and writes the patrol reports.\\n- **Motive**: Wants to be trusted with something that matters instead of copying reports.\\n- **Stance**: Trapped\\n- **Trait**: Still learning which questions are safe to ask out loud.\\n- **Wants right now**: Needs someone to explain why two patrol reports disagree before Marta reads them.\\n- **Leverage**: Owes her place to Marta and has not yet realised what that will cost her.\\n- **Connection**: reports to, and is quietly used by (Marta Oake)","lore":"### At a Glance\\n- **Structure**: Council\\n- **Emphasis**: Internal dissent\\n- **Immediate Hook**: Joss's petition will force the vote Marta has been delaying for months.\\n### How This Roster Divides\\nThe wardens and the riders agree the forest should survive; they disagree, bitterly, on what that costs.","labels":["faction-roster","faction-roster-generator","imported-draft"],"connections":[{"targetTitle":"The Ironwood Rangers","relationship":"member of"}]}`,
  "secret-society": `{"title":"The Quiet Gardeners","summary":"A charitable order whose free allotments are slowly replacing the city's food supply with plants that obey them.","lore":"## Belief & Doctrine\\nThe Gardeners teach that the city is a field gone to weed, and that patient tending will make it whole.\\n## Public Face\\nThey plant free vegetable plots on every waste lot, and the poorest wards love them for it.\\n## Secret Truth\\nThe seeds come from a single mother plant beneath their greenhouse, and everyone who eats the harvest dreams its dreams.\\n## Adventure Hooks\\nA dockhand who stopped eating the free greens is being followed by people who smile too evenly.","labels":["secret-society","cult","urban"],"connections":[]}`,
  creature: `{"title":"Mire-Gorged Basilic","summary":"An amphibious basilisk nesting in silted aqueducts whose petrifying gaze works only through still water reflections.","content":"### At a Glance\\n- **Classification**: Monstrous Beast\\n- **Size & Form**: Large (six-limbed serpentine quad)\\n- **Habitat**: Subterranean Sewers & Silted Aqueducts\\n- **Threat Level**: Dangerous Encounter\\n- **Temperament / Sapience**: Territorial Ambush Predator\\n- **Ecological Role**: Apex Sump Predator\\n\\n### Appearance & Anatomy\\nA dense serpentine reptile covered in thick jade scales encrusted with river limestone. Six splayed webbed talons allow it to cling upside-down to stone masonry, and milky secondary eyelids protect its sight underwater.\\n\\n### Core Concept & Ecology\\nNests in sluggish drainage sumps, damming stagnant gutters to create mirror-still hunting pools. It preys on calcified fish, giant rodents, and unwary tunnel scavengers.\\n\\n### Observable Abilities & Defences\\n- **Reflective Petrifying Gaze**: Its amber eyes emit a calcifying curse when perceived across still water surfaces.\\n- **Limestone Armor**: Dorsal plates resist cutting blades and acid.\\n\\n### Known Weaknesses & Limitations\\n- **Water Turbulence**: Any ripples, currents, or agitated surfaces break its gaze reflection.\\n- **Brittle Underbelly**: Its soft ventral plates lack limestone shielding.\\n\\n### Combat & Encounter Behaviour\\nLurks motionless beneath still sumps with only its ocular ridges breaking the surface. Strikes from ambush, dragging immobilized targets beneath the water before retreating if violently disturbed.\\n\\n### Harvest & Remains\\nIntact bile sacs yield petrification solvent; limestone-infused scales serve as acid-resistant plating.\\n\\n### Known Lore & Signs\\n- **Signs**: Calcified river rats frozen in mid-stride along canal banks; sudden unnatural stillness in running gutters.\\n- **Common Belief**: Dockers believe looking directly into the canal at night petrifies you instantly.","lore":"### True Origin & Hidden Ecology\\nThe creature was bred centuries ago by sewer-builders to calcify leaking masonry; surviving specimens carry dormant egg clutches that hatch only in the presence of alchemical waste spills.\\n\\n### Hidden Abilities & Surprises\\n- **Caustic Silt Cloud**: When reduced to half vitality, it thrashes violently to release a blinding cloud of caustic sediment that burns eyes and lungs.\\n\\n### Secret Weaknesses\\n- **Alchemical Vinegar**: Dousing its eye-ridges in strong acetic acid dissolves its ocular membranes, permanently disabling its petrification curse.\\n\\n### Tactical Notes\\n- **The Ceiling Drop**: Drops from vault ceilings into still cisterns behind players to catch their glance in the water behind them.\\n\\n### Truth Behind Rumours\\n- **Local Legend**: Looking into its living eye petrifies you.\\n- **The Reality**: Its direct gaze is harmless; only reflected light through perfectly still water focuses the calcifying curse.\\n\\n### Adventure & Encounter Hooks\\n- **The Blocked Sump**: City drainage has backed up with calcified statues; plumbers offer a bounty for safe escort.\\n- **The Solvent Hunt**: An apothecary hires the party to capture a living specimen to extract gaze-reversal bile.","labels":["creature","monster-generator","monstrous-beast","aquatic"],"connections":[{"targetTitle":"Undercity of Kesk","relationship":"nests beneath"}]}`,
  holiday: `{"title":"Shearing Day Truce","summary":"A highland observance where feuding clans shear each other's flocks and no blade may be raised in anger until dusk.","content":"A spring truce born from a famine year when rival clans could only survive by working together.","lore":"## GM Notes\\nThe official story credits a clan chief; the shepherds remember a widow who walked between the camps unarmed.","labels":["holiday-generator","observance","truce"],"connections":[],"observances":[{"name":"Shearing Day Truce","type":"Truce","when":"The first dry day after the spring thaw","observers":"Highland clans and their shepherds","traditions":"Each clan shears a rival's flock and sends back the finest fleece","tension":"A boundary stone moved in the night challenges the old agreement"}]}`,
  heist: `{"title":"The Halden Seed Job","summary":"The crew has one night to lift a dormant seed cylinder from a biolab vault before its acceptance trial begins at dawn.","content":"### The Score\\nSteal the Halden Seed from the sub-level vault of the Halden Biolab before the acceptance trial begins at dawn.\\n\\n### The Prize\\nA hand-span cylinder of frozen seed stock, worth a fortune to the buyer and a disaster to the lab. The buyer wants it destroyed, the lab wants it certified, and the family whose genome it carries wants it back.\\n- **Where**: On the cold shelf in the sub-level vault, behind the gated lift.\\n- **Window**: Only while the vault is unlocked for the dawn trial preparation.\\n- **Protection**: The insulated case, and the two technicians who alone may open it.\\n- **Once it is done**: The trial cannot proceed, and the lab board knows within the hour.\\n- **The catch**: Fragile. A hard knock breaks the seal, and a thawed Seed pays nothing.\\n- **Pressure**: Each time it is moved, fought over, or dropped, it takes a mark. The third mark spoils it.\\n\\n### Casing the Target\\n- **Entry vector**: The service door stays unlocked from the evening lockdown until the last shift change, and the night archivist who locks it takes a long break first.\\n- **Known obstacle**: The sub-level lift is gated, and the key hangs on the archivist's belt rather than a hook.\\n- **The prize**: It sits in an insulated case on the cold shelf, moved only by two technicians together, at dawn.","lore":"### GM Quick Reference\\n- **Objective**: Get the Halden Seed out of the biolab sub-level before dawn.\\n- **Primary obstacle**: Security drones, the archivist's gate key, and a sealed insulated case.\\n- **Hidden factor**: A technician has been sleeping in the sub-level vault since the cylinder arrived.\\n- **Point of no return**: Lifting the cylinder trips the silent containment alarm.\\n- **Pressure**: Three hard knocks spoil the Seed and the job pays nothing.\\n- **Default complication**: The buyer is already waiting in the atrium to take delivery.\\n- **Escape problem**: The service door becomes the guards' muster point.\\n\\n### The Hidden Factor\\nA technician has slept in the sub-level vault since the cylinder arrived, and nobody upstairs knows. It costs the crew a silent approach, not the approach itself. The technician can be avoided, woken elsewhere, or given a reason to leave.\\n\\n### Security Rings\\n- **Perimeter**: Two patrol drones loop the outer fence. Time the gap at the north gate, arrive openly with the morning shift, or cross the roof of the cooling tower, which nobody watches.\\n- **Access**: The lift gate and the key on the archivist's belt. Lift it while the archivist is on break, get a technician to escort you down for a plausible errand, or pull the door bolts, which are older than the lock.\\n- **Inner Vault**: The insulated case, locked and heavy. Pick it, give a technician a legitimate reason to open it, or take the whole case and solve its weight outside.\\n\\n### Alarm Track\\n- **0 — Quiet**: Evening routine. Drones on their loop, archivist on break, sub-level dark.\\n- **1 — Suspicion**: A drone doubles back to the service door it thinks was left shut. Patrol timings stop being predictable.\\n- **2 — Alert**: The archivist finds the gate key gone. Guards come in off the fence to watch the doors, but the work continues.\\n- **3 — Lockdown**: The outer doors are sealed from inside and the lab board is woken. Moving between floors now costs noise or a favour, though the service door is a staff door and stays as it was.\\n- **4 — Lethal Response**: The vault guard, three sworn blades who sleep armoured, are hunting to kill. They cover the exits, but they answer to the Seed and will break off to protect it.\\n\\n### Complications\\n- **The buyer is early (default)**: They are already in the atrium, waiting to take delivery before the crew has the prize.\\n- **A rival crew**: They have come for the Seed the same night and will trip the alarm first.\\n- **A familiar face**: The sleeping technician is someone in the crew knows by name.\\n\\n### When the Prize Is Taken\\nThe silent containment alarm begins to pulse despite having no audible siren. The alarm jumps to Alert, and the guards muster at the service door, the way the crew came in.\\n\\n### The Getaway\\nThe service door is the guards' muster point, so the way in is gone.\\n- **Fast but exposed**: Through the atrium and out the west dock, past every worker on the morning shift.\\n- **Covert but slow**: The maintenance tunnel under the sub-level, slow enough that the pursuit reaches the river first.\\n- **Hard route**: Up the cooling tower and across the roofs, where one slip spoils a fragile prize.\\n**Pursuit**: The vault guard, who are paid to recover the Seed intact and will follow it anywhere.\\n\\n### Flashback Opportunities\\n- A junior technician bribed a month ago who is on shift tonight\\n- A forged clearance from the agency's records office\\n- A pry bar cached behind a supply crate on the loading deck\\n- Prior reconnaissance of the archivist's break habits\\n- Knowledge of how the lift gate was fitted, from the engineer who installed it","labels":["heist","heist-generator","infiltration"],"connections":[{"targetTitle":"Halden Biolab","relationship":"targets"}]}`,
  "random-table": `{"title":"Night Market Encounters","summary":"A table of encounters and occurrences among the stalls after dark.","lore":"1. A watch patrol checking trading permits\\n2. A sudden {downpour} scattering the crowd under the awnings","labels":["table","encounters","random-table"],"connections":[]}`,
  encounter: `{"title":"The Dry Well Standoff","summary":"Two caravans need the same well before the midday heat peaks, and neither will leave first.","content":"### What the Players See\\nThe well at the crossroads holds enough water for one caravan. Two groups have already arrived and are watching each other from opposite rims, both with their animals panting in the sun.","lore":"### At a Glance\\n- **Encounter Type**: Mixed\\n- **Location**: Crossroads Well\\n- **Threat**: Moderate\\n- **Participants**: Four caravan guards and a six-strong raider band\\n- **Immediate Situation**: Both groups need the water before the heat closes the road for a day.\\n## What Is Happening\\nThe raiders are not bandits by trade. A drought has emptied their own wells, and this caravan's water and grain are the only supply within two days' travel.\\n## Goals & Stakes\\nThe guards must protect the cargo at any cost; the raiders will not survive the season without it. Left alone, this ends in a fight neither side can afford.\\n## Participants\\n- **Guard-Sergeant Corwen**, protecting the caravan on contract, not personally invested in the cargo's fate.\\n- **The raider band**, led by a former farmer, desperate rather than cruel.\\n## Environment\\nThe well is the only water on this stretch. The rocks around it offer the raiders cover the guards lack.\\n## Possible Approaches\\n- Negotiate a partial trade of water for safe passage.\\n- Help the guards hold the well until the evening cool brings the animals back to strength.\\n- Investigate the drought's cause to offer the raiders a better solution than theft.\\n## Complication / Twist\\nThe caravan's manifest is short by exactly what the raiders would have needed. Someone already skimmed it upstream.\\n## Outcomes & Consequences\\n- **Success**: A trade is brokered and the raiders disperse peacefully.\\n- **Failure**: Violence breaks out and the well is fouled.\\n- **Avoidance**: The two groups clash without the party, and the road stays dangerous.\\n- **Escalation**: The raiders return in greater numbers next season.\\n## Rewards / Discoveries\\nThe guard-sergeant's gratitude and a lead on who skimmed the manifest upstream.","labels":["encounter","encounter-generator","classic-fantasy"],"connections":[]}`,
  tome: `{"title":"The Thornmarch Herbal of Ninefold Remedies","summary":"An annotated herbal whose margins hide a second index of plants that heal in small doses and kill in large ones.","content":"### Physical Description & Format\\nBound in greased goatskin over split cedar boards with brass clasps gone green. The 96 leaves are thick rag paper, foxed brown at the edges and smelling of dried sage. The text is written in a neat apothecary hand using walnut-gall ink. Across eleven pages in the middle gathering, the plant names have been scraped and rewritten in the margins in a cramped cipher of symbols.\\n\\n### Provenance & Transmission\\nCompiled in 1611 by Apothecary Gerit Thorn for the infirmary of Thornmarch. Passed through three generations of village healers before acquisition in 1889 by a private collector, Lady Auberon Vey. Following Vey's death in 1904, the volume was catalogued as Lot 88 in the estate sale of the Thornmarch Society.\\n\\n### Contents & Revelations\\nOutwardly a standard herbal of remedies, the cipher glosses record a second index that matches each healing plant with the dose at which it turns lethal. A flyleaf in the back reveals that the infirmary's wardens kept this index to decide who could be safely given the strong draughts.\\n\\n### Risks & Costs of Study\\n- **Physical**: The dry paper gives off a fine dust that irritates the lungs; handling without a mask causes coughing and a numb tongue.\\n- **Social / Legal**: The estate sale has been reported as irregular, and the constabulary consider anyone holding Lot 88 a likely suspect in a poisoning.\\n- **Mental**: Working through the cipher for more than an hour brings on a persistent sense that someone is reading over the shoulder.\\n\\n### Adventure Hooks\\n1. **The Missing Leaves**: A dealer offers a substantial sum for three loose leaves from an auction, to verify whether they belong to Lot 88.\\n2. **The Winter Draught**: A village healer begins dosing the sick from a tincture whose recipe matches the cipher index, and the sick are not recovering.\\n3. **The Heir's Letter**: Lady Vey's grandniece finds a coded letter claiming her grandaunt did not die of illness, but of the index itself.","lore":"### At the Table Reference\\n\\n### Ground Truth for the GM\\n- **What the Book Claims**: Gerit Thorn records that the strong draughts in the middle gathering cure fevers when given in measured doses.\\n- **The Deception / Flaw**: Thorn used the index to remove patients the wardens considered a burden. The draughts killed them at the recorded doses.\\n- **The Objective Truth**: The cipher index is accurate. Each dose it recommends is the lethal threshold for that patient's weight.\\n- **Actionable Clue**: A flyleaf notation dates a run of unexplained deaths to the exact winter the infirmary began using the index.\\n\\n### Connected Entities\\n- **Gerit Thorn** (Author / Origin): The apothecary who compiled the herbal for the infirmary.\\n- **Lady Auberon Vey** (Previous Owner): Collector whose death in 1904 remains unexplained.\\n- **The Thornmarch Society** (Custodian / Archive): The estate that sold Lot 88 quietly, and wants it kept out of the auction record.\\n- **The Wardens' Circle** (Pursuing Faction): Former infirmary wardens who still want the index back to finish their work.\\n\\n### Quick Checks & Mechanics\\n- **Deciphering**: Requires Herbalism for the plant names; the cipher margins need Linguistics or two days of patient comparison against the body text.\\n- **The Failure Condition**: If the characters prepare a draught from the cipher index without checking the weight, the patient collapses within two rounds and cannot be revived by ordinary remedies.\\n- **Safe Handling**: Store in cedar shavings to keep the dust down; never read by open flame, as the dried resin in the spine is flammable.","labels":["tome","forbidden-book","grimoire","occult","investigation","item"],"connections":[{"targetTitle":"The Thornmarch Society","relationship":"catalogued in collection of"}]}`,
  business: `{"title":"Chrome Lily","summary":"A ripper clinic above the noodle stalls, run by a former corporate surgeon who now treats couriers and dockworkers.","content":"## Identity\\n**Chrome Lily** — Ripper clinic\\nA clinic above the noodle stalls.\\n\\n## Key Staff\\n- **Tomo Ruiz**, Technician — Quick hands.","lore":"","labels":["business","business-generator"],"connections":[{"targetTitle":"Helix Medical Corp","relationship":"competes with"}]}`,
  "point-crawl": `{"title":"The Glassfields of Vesk Hollow","summary":"An eight-node wilderness point crawl linking a fallen observatory, glass-sand dunes and a sealed mountain pass.","content":"## Crawl Premise & Entry\\nA field of glass-sand separates the frontier waystation from the Sealed Pass Fort, forcing the expedition to choose between exposed ridge trails, shifting dunes and smuggler shortcuts.\\n\\n## Keyed Locations\\n### 1. Ranger's Waystation *(Start Point)*\\nA timber watch-post above the glass-sand where surviving scouts trade route intelligence.\\n\\n### 2. Fallen Observatory *(Junction Hub)*\\nA half-buried dome whose central lens still holds the Iron Lattice Key.","lore":"## GM Navigation & Key-Lock Reference\\n- **Locked Route**: Ash Quarry to Sealed Pass Fort requires the Iron Lattice Key found at the Fallen Observatory.","labels":["point-crawl","point-crawl-generator","wilderness"],"connections":[]}`,
};
